M='''一=один;医=лечить, медицина (医生 врач);夏=лето (夏天);事=дело (没事儿);室=комната (办公室);五=пять;午=полдень (中午);京=столица (北京);睛=глаз (眼睛);以=чтобы, с помощью (可以, 以后);椅=стул (椅子);作=делать, работа (工作);做=делать;候=время, ждать (时候);公=общественный (公司);工=работа (工作);兴=радость (高兴);星=звезда (星期);办=делать, решать (办公室);加=добавлять (加油);友=друг (朋友);叫=звать(ся);可=можно (可以);司=управлять (公司);思=думать (意思);斯=частица в именах (俄罗斯);名=имя (名字);明=ясный, завтрашний (明天);啡=часть слова «кофе» (咖啡);非=не- (非常);喜=радость (喜欢);洗=мыть (洗澡);快=быстрый;筷=палочки (筷子);字=иероглиф (名字);自=сам (自行车);店=магазин (饭店);电=электричество (电影, 电脑);戴=носить (очки);数=число (数学);术=искусство (美术);早=рано, утро (早上);澡=купание (洗澡);时=время (时间);识=знать (认识);食=еда (甜食);晚=поздно, вечер (晚上);月=месяц, луна;越=всё более (越来越);每=каждый;美=красивый (美国);男=мужской (男朋友);语=язык (英语);雨=дождь (下雨);入=входить;八=восемь;太=слишком;夫=муж;日=день, солнце;目=глаз;白=белый;百=сто;末=конец (周末);未=ещё не;木=дерево;牛=корова;年=год;问=спрашивать (问题);间=промежуток (时间);门=дверь;们=суффикс мн. числа (我们);今=нынешний (今天);令=приказ;会=уметь;休=отдыхать (休息);体=тело (体育);贝=ракушка;现=сейчас (现在);王=король, фамилия Ван;主=главный;玉=нефрит;子=ребёнок, суффикс (孩子);朋=друг (朋友);饭=еда, рис (米饭);板=доска (老板);浅=мелкий;千=тысяча;干=сухой, делать;于=в, на (книжн.);儿=сын, суффикс -р (哪儿);九=девять;为=для, ради;力=сила;爸=папа;把=брать, держать;妈=мама;吗=вопросительная частица;码=код, номер;地=земля, место (地铁);得=частица степени;行=идти, можно;东=восток (东西);乐=радость, музыка (音乐);土=земля, почва;士=учёный, воин'''
import json
d={}
for p in M.split(';'):
    a,b=p.split('=',1); d[a]=b
open('charru.js','w').write('const CHARRU='+json.dumps(d,ensure_ascii=False)+';\n')
print(len(d))
